INSERT INTO ontology (id, name, uri, description, position, license, license_url, retrieved) VALUES
  ('schema', 'Schema.org', 'https://schema.org/', 'Shared vocabulary for structured data on the web.', '0', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0/', '2026-11-04'),
  ('gs1', 'GS1 Web Vocabulary', 'https://ref.gs1.org/voc/', 'Ontology of product, party and regulatory data for GS1 identified goods.', '1', 'Apache-2.0', 'https://www.apache.org/licenses/LICENSE-2.0', '2026-11-04'),
  ('untp', 'UN Transparency Protocol', 'https://vocabulary.uncefact.org/untp/', 'UN/CEFACT vocabulary behind digital product passports and conformity credentials.', '2', 'GPL-3.0', 'https://github.com/uncefact/spec-untp/blob/main/LICENSE', '2026-11-04'),
  ('oeo', 'Open Energy Ontology', 'https://openenergyplatform.org/ontology/oeo/', 'OWL ontology of energy systems, emissions and their economics.', '3', 'CC0 1.0', 'https://creativecommons.org/publicdomain/zero/1.0/', '2026-11-04'),
  ('ncit', 'NCI Thesaurus OBO Edition', 'http://purl.obolibrary.org/obo/ncit.owl', 'OWL edition of the National Cancer Institute''s reference terminology, in the OBO Foundry.', '4', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', '2026-11-04'),
  ('gemet', 'GEMET', 'https://www.eionet.europa.eu/gemet/', 'The European Environment Agency''s General Multilingual Environmental Thesaurus. A thesaurus rather than a formal ontology.', '5', 'CC BY', 'https://www.eea.europa.eu/en/legal-notice', '2026-11-04'),
  ('wikidata', 'Wikidata', 'https://www.wikidata.org/', 'Community-edited knowledge base. Its descriptions are short and can change.', '6', 'CC0 1.0', 'https://creativecommons.org/publicdomain/zero/1.0/', '2026-11-04');
INSERT INTO ontology_term (id, ontology_id, label, uri, definition, position) VALUES
  ('schema:productID', 'schema', 'productID', 'https://schema.org/productID', 'The product identifier, such as ISBN.', '0'),
  ('schema:material', 'schema', 'material', 'https://schema.org/material', 'A material that something is made from, e.g. leather, wool, cotton, paper.', '1'),
  ('schema:substanceOfConcern', 'schema', 'substanceOfConcern', 'https://schema.org/substanceOfConcern', 'A substance of concern (SoC) contained within the product, typically based on regulatory lists like REACH or RoHS.', '2'),
  ('schema:recycledContentPercentage', 'schema', 'recycledContentPercentage', 'https://schema.org/recycledContentPercentage', 'The percentage of recycled material in the product.', '3'),
  ('schema:DeclarationOfConformity', 'schema', 'DeclarationOfConformity', 'https://schema.org/DeclarationOfConformity', 'A Declaration of Conformity (DoC), a formal document issued by a manufacturer declaring that a product meets specific regulatory requirements.', '4'),
  ('schema:DigitalProductPassport', 'schema', 'DigitalProductPassport', 'https://schema.org/DigitalProductPassport', 'A digital product passport (DPP), a record containing information about a product''s lifecycle, sustainability, and compliance.', '5'),
  ('gs1:manufacturer', 'gs1', 'Has Manufacturer', 'https://ref.gs1.org/voc/manufacturer', 'The organization that produces the item.', '6'),
  ('gs1:OrganizationRoleType-IMPORTER', 'gs1', 'Importer', 'https://ref.gs1.org/voc/OrganizationRoleType-IMPORTER', 'Organization who makes - or on whose behalf a Customs clearing agent or other authorized person makes - an import declaration. This may include a person who has possession of the goods or to whom the goods are consigned.', '7'),
  ('gs1:RegulationTypeCode-TREATED_WITH_BIOCIDE_REGULATION', 'gs1', 'Biocide regulation treated article', 'https://ref.gs1.org/voc/RegulationTypeCode-TREATED_WITH_BIOCIDE_REGULATION', 'Regulation (e.g., EU Reg 528/2012) harmonising the rules on making available on the market and trade items treated with biocidal products (''treated articles''), whilst ensuring a high level of protection of both human and animal health and the environment.', '8'),
  ('gs1:consumerRecyclingInstructions', 'gs1', 'Consumer Recycling Instructions', 'https://ref.gs1.org/voc/consumerRecyclingInstructions', 'Expresses in text the consumer recycling instructions which are normally held on the label or accompanying the product. Instructions may refer to the ''how'' the consumer is supposed to sort the product and packaging materials for recycling.', '9'),
  ('gs1:countryOfOrigin', 'gs1', 'Has Country Of Origin', 'https://ref.gs1.org/voc/countryOfOrigin', 'Code indicating the country of origin of the product.', '10'),
  ('gs1:RegulatoryIdentifierType-DUE_DILIGENCE_STATEMENT', 'gs1', 'Due Diligence Statement', 'https://ref.gs1.org/voc/RegulatoryIdentifierType-DUE_DILIGENCE_STATEMENT', 'A document or dataset that states the due diligence activities undertaken by a person or organization to meet regulatory compliance requirements.', '11'),
  ('gs1:consumerUsageInstructions', 'gs1', 'Consumer Usage Instructions', 'https://ref.gs1.org/voc/consumerUsageInstructions', 'Free text containing the usage instructions of a product, which are normally held on the label or accompanying the product.', '12'),
  ('gs1:consumerSafetyInformation', 'gs1', 'Consumer Safety Information', 'https://ref.gs1.org/voc/consumerSafetyInformation', 'Information on consumer safety regarding the product.', '13'),
  ('untp:registeredId', 'untp', 'registeredId', 'https://vocabulary.uncefact.org/untp/registeredId', 'The registration number (alphanumeric) of the Party within the register. Unique within the register.', '14'),
  ('untp:massFraction', 'untp', 'massFraction', 'https://vocabulary.uncefact.org/untp/massFraction', 'The mass fraction as a decimal of the product (or facility reporting period) represented by this material.', '15'),
  ('untp:quantity', 'untp', 'quantity', 'https://vocabulary.uncefact.org/untp/quantity', 'The quantity of product subject to this lifecycle event.', '16'),
  ('untp:ProductStatus#disposed', 'untp', 'Disposed', 'https://vocabulary.uncefact.org/untp/ProductStatus#disposed', 'Product has reached end of life and has been disposed of or destroyed without material recovery.', '17'),
  ('untp:Facility', 'untp', 'Facility', 'https://vocabulary.uncefact.org/untp/Facility', 'The physical site (eg farm or factory) where the product or materials was produced.', '18'),
  ('untp:Party', 'untp', 'Party', 'https://vocabulary.uncefact.org/untp/Party', 'An organisation. May be a supply chain actor, a certifier, a government agency.', '19'),
  ('untp:AssessorLevel#3rdParty', 'untp', 'Independent third party assessment', 'https://vocabulary.uncefact.org/untp/AssessorLevel#3rdParty', '3rd party (independent) conformity assessment', '20'),
  ('untp:Performance', 'untp', 'Performance', 'https://vocabulary.uncefact.org/untp/Performance', 'A claimed, assessed, or required performance level defined either by a scoring system or a numeric measure.', '21'),
  ('oeo:OEO_00000147', 'oeo', 'emission', 'https://openenergyplatform.org/ontology/oeo/OEO_00000147', 'emission is a process releasing by-products from human activity (e.g. production, distribution or consumption) into the environment.', '22'),
  ('oeo:OEO_00010210', 'oeo', 'energy use', 'https://openenergyplatform.org/ontology/oeo/OEO_00010210', 'Energy use is the consumption of an energy carrier making use of the energy it carries.', '23'),
  ('oeo:OEO_00010269', 'oeo', 'CO2 price', 'https://openenergyplatform.org/ontology/oeo/OEO_00010269', 'A CO2 price is an emission price of emitting a certain CO2 emission value.', '24'),
  ('ncit:C48044', 'ncit', 'Precursor', 'http://purl.obolibrary.org/obo/NCIT_C48044', 'A substance from which another substance is formed.', '25'),
  ('ncit:C43361', 'ncit', 'Barcode', 'http://purl.obolibrary.org/obo/NCIT_C43361', 'A machine-readable representation of information in a visual format on a surface.', '26'),
  ('gemet:15155', 'gemet', 'environmental footprint', 'http://www.eionet.europa.eu/gemet/concept/15155', 'environmental impact of a product, a service, and/or a company, over its lifecycle', '27'),
  ('gemet:15279', 'gemet', 'resource use', 'http://www.eionet.europa.eu/gemet/concept/15279', 'appropriation and use of resources, ecosystems and naturally occurring materials, such as soil, wood, water, and minerals', '28'),
  ('gemet:3854', 'gemet', 'hazardous substance', 'http://www.eionet.europa.eu/gemet/concept/3854', 'Any material that poses a threat to human health and/or the environment. Typical hazardous substances are toxic, corrosive, ignitable, explosive, or chemically reactive.', '29'),
  ('gemet:7009', 'gemet', 'recyclability', 'http://www.eionet.europa.eu/gemet/concept/7009', 'Characteristic of materials that still have useful physical or chemical properties after serving their original purpose and that can, therefore, be reused or remanufactured into additional products.', '30'),
  ('gemet:4566', 'gemet', 'labelling', 'http://www.eionet.europa.eu/gemet/concept/4566', 'Attaching a notice to a product or container bearing information concerning its contents, proper use, manufacturer and any cautions or hazards of use.', '31'),
  ('wikidata:Q55237506', 'wikidata', 'Harmonized System Code', 'https://www.wikidata.org/wiki/Q55237506', 'identifier of a good, product or object that may be traded internationally and is classified in the Harmonized System', '32'),
  ('wikidata:Q629103', 'wikidata', 'animal product', 'https://www.wikidata.org/wiki/Q629103', 'material derived from the bodies of animals', '33'),
  ('wikidata:Q310667', 'wikidata', 'carbon footprint', 'https://www.wikidata.org/wiki/Q310667', 'total set of greenhouse gas emissions caused by an individual, event, organisation, or product, expressed as carbon dioxide equivalent', '34'),
  ('wikidata:Q6839919', 'wikidata', 'microplastics', 'https://www.wikidata.org/wiki/Q6839919', 'fragments of plastic less than 5 mm in length', '35'),
  ('wikidata:Q10269116', 'wikidata', 'durability', 'https://www.wikidata.org/wiki/Q10269116', 'ability of an item to perform its role over a long period of time under potentially challenging conditions', '36'),
  ('wikidata:Q30748592', 'wikidata', 'repairability', 'https://www.wikidata.org/wiki/Q30748592', 'the degree to which something can be repaired, including the ease of doing so', '37'),
  ('wikidata:Q705818', 'wikidata', 'forced labor', 'https://www.wikidata.org/wiki/Q705818', 'work people are employed in, but against their will', '38');
INSERT INTO data_requirement_term (data_requirement_id, term_id, match, note) VALUES
  ('product-id', 'schema:productID', 'close', 'Names the identifier; says nothing of the uniqueness or persistence ESPR asks for.'),
  ('commodity-code', 'wikidata:Q55237506', 'close', 'The CN code used in the EU extends this six-digit code.'),
  ('manufacturer', 'gs1:manufacturer', 'close', 'Defines the party, not its contact details.'),
  ('importer', 'gs1:OrganizationRoleType-IMPORTER', 'close', 'Defines the importer, not the EU responsible operator.'),
  ('producer-registration', 'untp:registeredId', 'close', 'A number in any register; the acts mean national registers of producers.'),
  ('material-composition', 'schema:material', 'close', 'The material itself.'),
  ('material-composition', 'untp:massFraction', 'close', 'The share of the product that material makes up.'),
  ('animal-origin', 'wikidata:Q629103', 'broad', 'Any material from animals, not only non-textile parts.'),
  ('substances-of-concern', 'schema:substanceOfConcern', 'close', 'Pending in Schema.org. ESPR sets its own legal definition.'),
  ('restricted-substances', 'gemet:3854', 'broad', 'No open vocabulary we searched defines a restricted substance; this is the wider class restrictions draw from.'),
  ('biocidal-treatment', 'gs1:RegulationTypeCode-TREATED_WITH_BIOCIDE_REGULATION', 'close', 'Defines the rule for treated articles, not the data their label must carry.'),
  ('carbon-footprint', 'wikidata:Q310667', 'close', 'Embedded emissions under CBAM have a narrower boundary.'),
  ('environmental-footprint', 'gemet:15155', 'exact', NULL),
  ('process-emissions', 'oeo:OEO_00000147', 'broad', 'Any emission from human activity; the production route has no term of its own.'),
  ('energy-resources', 'oeo:OEO_00010210', 'close', 'The energy part.'),
  ('energy-resources', 'gemet:15279', 'close', 'The resource part.'),
  ('precursors', 'ncit:C48044', 'broad', 'A chemical sense; CBAM precursors are input goods with embedded emissions.'),
  ('carbon-price', 'oeo:OEO_00010269', 'close', 'CBAM counts only a price paid in the country of origin.'),
  ('microplastics', 'wikidata:Q6839919', 'close', 'Defines the particles, not their release.'),
  ('recycled-content', 'schema:recycledContentPercentage', 'exact', 'Pending in Schema.org.'),
  ('durability', 'wikidata:Q10269116', 'exact', NULL),
  ('repairability', 'wikidata:Q30748592', 'exact', NULL),
  ('recyclability', 'gemet:7009', 'close', 'Describes materials; ESPR also looks at design for recycling.'),
  ('end-of-life-info', 'gs1:consumerRecyclingInstructions', 'close', 'Consumer recycling and sorting only, not deconstruction or disposal information.'),
  ('quantities', 'untp:quantity', 'broad', 'The quantity in any lifecycle event; no open term covers quantities placed on the market.'),
  ('unsold-products', 'untp:ProductStatus#disposed', 'broad', 'Any disposed product; no open term separates unsold ones.'),
  ('production-site', 'gs1:countryOfOrigin', 'close', 'The country.'),
  ('production-site', 'untp:Facility', 'close', 'The site.'),
  ('supply-chain-operators', 'untp:Party', 'broad', 'Any party, of which supply-chain actors are one kind.'),
  ('forced-labour', 'wikidata:Q705818', 'close', 'The Forced Labour Regulation defines the term through ILO conventions.'),
  ('forced-labour', 'gs1:RegulatoryIdentifierType-DUE_DILIGENCE_STATEMENT', 'close', 'The due diligence part.'),
  ('conformity', 'schema:DeclarationOfConformity', 'close', 'Pending in Schema.org. Does not cover the declaration of performance under the CPR.'),
  ('verification', 'untp:AssessorLevel#3rdParty', 'exact', NULL),
  ('performance', 'untp:Performance', 'close', 'A performance level; the acts also cover the characteristics behind it.'),
  ('dpp', 'schema:DigitalProductPassport', 'exact', 'Pending in Schema.org.'),
  ('dpp', 'ncit:C43361', 'narrow', 'The data carrier part: barcodes are one kind, and ESPR allows others.'),
  ('instructions', 'gs1:consumerUsageInstructions', 'close', 'Instructions for use.'),
  ('instructions', 'gs1:consumerSafetyInformation', 'close', 'Safety information.'),
  ('label', 'gemet:4566', 'close', 'The act of labelling rather than the label.');
